const grid=document.querySelector('#food-grid');const dialog=document.querySelector('#result');let filter='all',chosen=null,busy=false,treats=0,toastTimer;
function render(){grid.replaceChildren();foods.filter(f=>filter==='all'||f.groups.includes(filter)).forEach(food=>{const card=document.createElement('button');card.className='food-card';card.dataset.id=food.id;card.setAttribute('aria-label',`Wybierz: ${food.name}`);card.innerHTML=`<div class="food-art" style="background:${food.color}"><span class="food-tag">${food.tag}</span><span class="food-emoji" aria-hidden="true">${food.emoji}</span></div><div class="food-info"><h3>${food.name}</h3><p>${food.description}</p><span class="food-arrow" aria-hidden="true">↗</span></div>`;card.addEventListener('click',()=>showResult(food));grid.append(card);});}
function showResult(food){chosen=food;document.querySelector('#result-emoji').textContent=food.emoji;document.querySelector('#result-name').textContent=food.answer;document.querySelector('#result-copy').textContent=food.quote;document.querySelector('#confirmation').textContent='';document.querySelector('#confirm').textContent='To jest to! ♡';document.querySelectorAll('.food-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===food.id));if(!dialog.open)dialog.showModal();}
function randomPick(){if(busy)return;busy=true;const pool=foods.filter(f=>(filter==='all'||f.groups.includes(filter))&&f.id!==chosen?.id);const options=pool.length?pool:foods;document.querySelector('#dog-speech').textContent='Węszenie w toku… Decyzja wymaga łapysłu.';document.querySelector('#dog').classList.add('happy');document.querySelectorAll('#random, #dog-pick, #again').forEach(b=>b.disabled=true);setTimeout(()=>{const pick=options[Math.floor(Math.random()*options.length)];showResult(pick);document.querySelector('#dog-speech').textContent=`„Wybieram: ${pick.name.toLowerCase()}. Możecie mi podziękować smaczkiem.”`;document.querySelector('#dog').classList.remove('happy');document.querySelectorAll('#random, #dog-pick, #again').forEach(b=>b.disabled=false);busy=false;},650);}
function confetti(){const area=document.querySelector('#confetti');area.replaceChildren();for(let i=0;i<28;i++){const bit=document.createElement('span');bit.className='confetto';bit.textContent=['♡','✳','🐾','✧'][i%4];bit.style.left=`${Math.random()*100}%`;bit.style.color=['#ec603c','#8b9872','#b49bc5'][i%3];bit.style.animationDelay=`${Math.random()*.4}s`;area.append(bit);}setTimeout(()=>area.replaceChildren(),2600);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});render();}));
document.querySelector('#random').addEventListener('click',randomPick);document.querySelector('#dog-pick').addEventListener('click',randomPick);document.querySelector('#again').addEventListener('click',randomPick);document.querySelector('#close-result').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();}});
document.querySelector('#confirm').addEventListener('click',()=>{const decision={food:chosen.id,date:new Date().toLocaleDateString('sv-SE')};try{localStorage.setItem('klaudia-dinner',JSON.stringify(decision));}catch{}document.querySelector('#confirmation').textContent='Ustalone! Dobry wybór. Towarzystwo też niczego sobie. 😉';document.querySelector('#confirm').textContent='Kolacja zatwierdzona ✓';confetti();});
document.querySelector('#treat').addEventListener('click',()=>{treats++;const quotes=['„Smaczek przyjęty. Obiektywność doradcy zagrożona.”','„Jeszcze jeden i powiem, że pizza to warzywo.”','„Klaudia, jesteś moim ulubionym człowiekiem.”','„Oficjalnie: najlepsza praca na świecie.”'];document.querySelector('#dog-speech').textContent=quotes[(treats-1)%quotes.length];document.querySelector('#treat-count').textContent=`Smaczki na koncie: ${treats}. Ogonek: nie do zatrzymania.`;const dog=document.querySelector('#dog');dog.classList.remove('happy');void dog.getBoundingClientRect();dog.classList.add('happy');toast('Chrup! Wirtualny smaczek, prawdziwa radość. 🐾');});
render();try{const saved=JSON.parse(localStorage.getItem('klaudia-dinner'));if(saved?.date===new Date().toLocaleDateString('sv-SE')){const food=foods.find(f=>f.id===saved.food);if(food){chosen=food;document.querySelector('#dog-speech').textContent=`„Pamiętam! Dziś wybraliście: ${food.name.toLowerCase()}. Dobry wybór.”`;}}}catch{}
